CREATE TABLE IF NOT EXISTS pupils(id INTEGER PRIMARY KEY AUTOINCREMENT,username TEXT UNIQUE NOT NULL,class TEXT,pin_hash TEXT NOT NULL,created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,role TEXT NOT NULL,pupil_id INTEGER,created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS fails(k TEXT PRIMARY KEY,n INTEGER,ts INTEGER);
CREATE TABLE IF NOT EXISTS teachers(id INTEGER PRIMARY KEY AUTOINCREMENT,username TEXT UNIQUE NOT NULL,salt TEXT NOT NULL,hash TEXT NOT NULL,created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS teacher_classes(teacher_id INTEGER,class TEXT,PRIMARY KEY(teacher_id,class));
CREATE TABLE IF NOT EXISTS hl_log(id INTEGER PRIMARY KEY AUTOINCREMENT,pupil_id INTEGER,mode TEXT,story TEXT,area TEXT,tap TEXT,r TEXT,ts TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS hl_stars(pupil_id INTEGER,mode TEXT,story TEXT,stars INTEGER,PRIMARY KEY(pupil_id,mode,story));
CREATE INDEX IF NOT EXISTS i_hl_log ON hl_log(pupil_id,mode,story);
CREATE TABLE IF NOT EXISTS hl_stories(id TEXT PRIMARY KEY,data TEXT,active INTEGER DEFAULT 1,author TEXT,author_name TEXT,created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS plan_pref(pupil_id INTEGER PRIMARY KEY,shape TEXT);
CREATE TABLE IF NOT EXISTS plan_default(class TEXT PRIMARY KEY,shape TEXT);
